function t(clave, v = {}) {
  const tabla = TEXTOS[Idioma.actual()] || TEXTOS.es;
  const valor = tabla[clave] ?? TEXTOS.es[clave];
  if (valor === undefined) return clave.startsWith('mundo.') ? clave.slice(6) : clave;
  return typeof valor === 'function' ? valor(v) : valor;
}

const Idioma = (() => {
  const delNavegador = () => { const l = (navigator.language || 'es').slice(0, 2); return IDIOMAS[l] ? l : 'es'; };
  let actual = IDIOMAS[Config.get('idioma')] ? Config.get('idioma') : delNavegador();
  const originales = new Map();   // catálogo → valores en español, para volver
  const guardarOriginal = (obj, campos) => { if (!originales.has(obj)) originales.set(obj, Object.fromEntries(campos.map(c => [c, obj[c]]))); return originales.get(obj); };
  const oyentes = [];
  return {
    actual: () => actual,
    elegir(id) {
      if (!IDIOMAS[id] || id === actual) return;
      actual = id; Config.set('idioma', id);
      this.aplicar();
      oyentes.forEach(f => f(id));
    },
    alCambiar(f) { oyentes.push(f); },
    // Traduce la página y los catálogos
    aplicar(raiz = document) {
      document.documentElement.lang = actual === 'pt' ? 'pt-BR' : actual;
      document.title = t('doc.titulo');
      raiz.querySelectorAll('[data-t]').forEach(el => { el.textContent = t(el.dataset.t); });
      raiz.querySelectorAll('[data-t-html]').forEach(el => { el.innerHTML = t(el.dataset.tHtml); });
      raiz.querySelectorAll('[data-t-mayus]').forEach(el => { el.textContent = t(el.dataset.tMayus).toUpperCase(); });
      raiz.querySelectorAll('[data-t-aria]').forEach(el => { el.setAttribute('aria-label', t(el.dataset.tAria)); });
      raiz.querySelectorAll('[data-t-title]').forEach(el => { el.title = t(el.dataset.tTitle); });
      for (const m of MISIONES) {
        const es = guardarOriginal(m, ['nombre', 'descripcion']), tr = TEXTOS_MISIONES[actual]?.[m.id];
        m.nombre = tr ? tr[0] : es.nombre; m.descripcion = tr ? tr[1] : es.descripcion;
      }
      for (const d of Object.values(DIFICULTADES)) {
        guardarOriginal(d, ['nombre', 'descripcion']);
        d.nombre = t('dif.' + d.id); d.descripcion = t('dif.' + d.id + '.desc');
      }
      GRUPOS_ARMAS.forEach((g, k) => { guardarOriginal(g, ['nombre']); g.nombre = t('grupo.' + k); });
      for (const id of ['recortada', 'm79', 'bazuca', 'granadas', 'laser', 'hacha', 'bate', 'mazo', 'tridente', 'egida', 'cuchillo']) if (ARMAS[id]) { guardarOriginal(ARMAS[id], ['nombre']); ARMAS[id].nombre = t('arma.' + id); }
    },
  };
})();
